cat > /tmp/test_regex.js << 'EOF'
// Test the regex pattern
const pattern = /^([a-z_]+)=([0-9.]+)$/;

const tests = [
  { input: 'exact_match=0.9', shouldMatch: true },
  { input: 'toxicity=0.5', shouldMatch: true },
  { input: 'length_variance=0.8', shouldMatch: true },
  { input: 'invalid format', shouldMatch: false },
  { input: 'ExactMatch=0.9', shouldMatch: false },  // uppercase
  { input: 'exact_match=1.5', shouldMatch: true },  // regex passes, but validation fails
  { input: 'exact_match', shouldMatch: false },
];

tests.forEach(test => {
  const match = pattern.test(test.input);
  const passed = match === test.shouldMatch ? '✓' : '✗';
  console.log(`${passed} ${test.input}: ${match}`);
});
EOF
node /tmp/test_regex.js
